from pathlib import Path
import json,hashlib,html,math

root=Path(__file__).resolve().parents[1];out=root/'output/link-verification'
read=lambda name:json.loads((out/name).read_text(encoding='utf-8-sig'))
unit=read('unit-results.json');assert unit['success'] and unit['numPassedTests']==415 and unit['numFailedTests']==0
groups=['api-results.json','export-format-results.json','cutting-results.json','ui-results.json','built-results.json'];counts={}
for name in groups:
    r=read(name);assert not r.get('errors') and not r.get('cloud');assert all(x['status']=='PASS' for x in r['results']);counts[name]=len(r['results'])
total=unit['numPassedTests']+sum(counts.values());assert total==437
for name in ['demo-build.log','production-build.log']:assert 'built in' in (out/name).read_text('utf-8-sig')
comparison=read('config-comparison.json')
for name,data in comparison.items():
    assert data['finalSha256']==hashlib.sha256((root/name).read_bytes()).hexdigest()
    assert data['baselineSha256']==data['finalSha256'],name+' changed; inspect concurrent edits before reporting'
checkpoint=read('checkpoint-verification.json');assert checkpoint['status']=='PASS'
pdf=read('pdf-results.json');assert pdf['renderedPages']==22 and all(r['status']=='PASS' for r in pdf['results'])
excel=read('render-results.json');assert excel['status']=='PASS' and excel['views']==4
ctx=read('context.json');assert ctx['expectedCuts']==[1675,1700] and ctx['workingCutLength']==42250
for a in ctx['artifacts']+ctx.get('previousArtifacts',[]):
    data=(out/a['local']).read_bytes();assert len(data)==a['size'] and hashlib.sha256(data).hexdigest()==a['sha256']
backup=out/'BS51-backup.zip'
summary={'version':'0.33.0','status':'PASS for tested software scope only','softwareScenarios':total,'unitTests':415,'testGroups':counts,'pdfPages':22,'workbookViews':4,'fullSystemAcceptance':False,'engineeringAccepted':False,'productionAccepted':False,'rulesDeployment':'User managed; explicitly declined','rulesFilesEditedByThisIncrement':False,'cloudChangesByThisIncrement':False,'configurationComparison':comparison,'checkpoint':checkpoint,'currentExportArtifacts':ctx['artifacts'],'preservedPreviousArtifacts':ctx.get('previousArtifacts',[]),'backupSha256':hashlib.sha256(backup.read_bytes()).hexdigest(),'backupScope':'Actual pre-wizard/pre-format-replay project backup and tested restore; not a claim that later UI/export-job changes are included','sourceEdition':'Supplied BS8666:2000 + Amendments1/2','sourceSha256':'9c6fa5d0bafd0a8761f14d1611c582d5db7d89710eaaf0910b5dc7c493e0cb43','enginePolicy':'geometry-2.2+bs8666-2000-v7','FrozenPieces':15,'WorkingPieces':25,'workingCutLengthMm':42250,'FrozenWeightKg':ctx['expectedWeight'],'nativeExcelPrintingVerified':False,'issuedEnabled':False,'productionStockConsumption':False}
(out/'verification-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
