link=lambda target,label:f'<a href="{esc(target)}">{esc(label)}</a>'
test_rows=''.join(f'<tr><td>{esc(name)}</td><td>{n}</td><td>PASS</td></tr>' for name,n in {'Unit tests':415,**counts}.items())
